package com.campus.lostfound.service; import com.campus.lostfound.repository.UserRepository; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; @Service public class PortalUserDetailsService implements UserDetailsService { private final UserRepository users; public PortalUserDetailsService(UserRepository users){this.users=users;} @Override public UserDetails loadUserByUsername(String email){var u=users.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Account not found")); return org.springframework.security.core.userdetails.User.withUsername(u.getEmail()).password(u.getPassword()).authorities(u.getRole()).disabled(!u.isEnabled()).build();} }